from datetime import datetime, timezone

# items is the upstream payload. Find the keys array wherever the MCP
# server put it. Defaults handle a few common response shapes.
src = items[0] if items else {}
if isinstance(src, dict):
    keys = src.get('keys') or src.get('resources') or src.get('result', {}).get('keys') or []
else:
    keys = []

by_cloud = {}
by_algorithm = {}
buckets = ['<30d', '30-90d', '90-180d', '180-365d', '>365d']
ageing = {b: 0 for b in buckets}
now = datetime.now(timezone.utc)

for k in keys:
    if not isinstance(k, dict):
        continue
    labels = k.get('labels') or k.get('metadata') or {}
    cloud = (labels.get('cloud') if isinstance(labels, dict) else None) or k.get('cloud') or 'unknown'
    algo = k.get('algorithm') or k.get('algo') or 'unknown'
    by_cloud[cloud] = by_cloud.get(cloud, 0) + 1
    by_algorithm[algo] = by_algorithm.get(algo, 0) + 1

    created_raw = k.get('createdAt') or k.get('created_at') or k.get('creationDate') or ''
    age_days = 0
    try:
        if isinstance(created_raw, str) and created_raw:
            dt = datetime.fromisoformat(created_raw.replace('Z', '+00:00'))
            age_days = (now - dt).days
    except Exception:
        age_days = 0
    if age_days < 30:
        ageing['<30d'] += 1
    elif age_days < 90:
        ageing['30-90d'] += 1
    elif age_days < 180:
        ageing['90-180d'] += 1
    elif age_days < 365:
        ageing['180-365d'] += 1
    else:
        ageing['>365d'] += 1

log({
    'byCloud': [{'category': c, 'count': n} for c, n in sorted(by_cloud.items(), key=lambda x: -x[1])],
    'byAlgorithm': [{'algorithm': a, 'count': n} for a, n in sorted(by_algorithm.items(), key=lambda x: -x[1])],
    'ageing': [{'bucket': b, 'count': ageing[b]} for b in buckets],
    'totalKeys': len(keys),
    'generatedAt': now.isoformat()
})
